local Layout = (function()
local Layout = {}

local function clamp(value, minimum, maximum)
    return math.max(minimum, math.min(value, maximum))
end

function Layout.compute(viewport, minimized, center)
    local availableWidth = math.max(1, viewport.X - 24)
    local availableHeight = math.max(1, viewport.Y - 24)
    local width = minimized and math.min(300, availableWidth) or math.min(680, availableWidth)
    local height = minimized and math.min(58, availableHeight) or math.min(440, availableHeight)
    local centerX = center and center.X or viewport.X / 2
    local centerY = center and center.Y or viewport.Y / 2
    centerX = clamp(
        centerX,
        math.min(viewport.X / 2, width / 2 + 12),
        math.max(viewport.X / 2, viewport.X - width / 2 - 12)
    )
    centerY = clamp(
        centerY,
        math.min(viewport.Y / 2, height / 2 + 12),
        math.max(viewport.Y / 2, viewport.Y - height / 2 - 12)
    )

    return {
        width = width,
        height = height,
        x = centerX - width / 2,
        y = centerY - height / 2,
        compact = viewport.X < 600,
    }
end

return Layout
end)()

local ConnectionScope = (function()
local ConnectionScope = {}

function ConnectionScope.new()
    local connections = {}
    local closed = false
    local scope = {}

    function scope.connect(signal, callback)
        assert(not closed, "Cannot connect a closed connection scope")
        local connection = signal:Connect(function(...)
            if not closed then
                callback(...)
            end
        end)
        table.insert(connections, connection)
        return connection
    end

    function scope.track(connection)
        assert(not closed, "Cannot track a connection in a closed scope")
        table.insert(connections, connection)
        return connection
    end

    function scope.disconnect(connection)
        for index = #connections, 1, -1 do
            if connections[index] == connection then
                table.remove(connections, index)
                if connection.Connected then
                    connection:Disconnect()
                end
                return true
            end
        end
        return false
    end

    function scope.close()
        if closed then
            return false
        end

        closed = true
        for index = #connections, 1, -1 do
            local connection = connections[index]
            if connection.Connected then
                connection:Disconnect()
            end
        end
        for index = #connections, 1, -1 do
            connections[index] = nil
        end
        return true
    end

    function scope.isClosed()
        return closed
    end

    return scope
end

return ConnectionScope
end)()

